import Foundation

/// The Anizium playback module, embedded so a fresh install can search and play
/// straight away with nothing to add. The manifest mirrors anizium.json and the
/// script mirrors anizium.js; `ModuleManager` registers the module at launch and
/// the update check leaves it alone because it carries no `jsonUrl`.
enum AniziumEmbeddedModule {
    /// Stable identity for the embedded module (`ModuleDefinition.id` is its scriptUrl).
    static let scriptURL = "https://anizium.co/modules/anizium.js"

    static let manifestJSON = #"""
        {
            "sourceName": "Anizium",
            "iconUrl": "https://anizium.co/assets/images/favicon.png",
            "author": {"name": "Ademi", "url": "https://ademi.ai"},
            "version": "1.1.0",
            "baseUrl": "https://anizium.co",
            "searchBaseUrl": "https://anizium.co",
            "scriptUrl": "https://anizium.co/modules/anizium.js",
            "type": "anime/shows/movies",
            "asyncJS": true,
            "streamType": "mp4",
            "quality": "4K",
            "language": "tr",
            "softsub": true
        }
        """#

    /// The module script, byte-for-byte the anizium.js the previous session verified
    /// against the live API (Cf-Control token, search, episodes, MP4 streams, subtitles).
    static let script = "var API_HOST = \"https://api.anizium.co\";\nvar TOKEN_KEY = \"hlxjl1c2w281ax473rt1ofgrvhyjvi\";\nvar CLIENT_KEY = \"16ghkdz5qnwinkyebwopbd94b49xhs\";\nvar DAY_NAMES = [\"sunday\", \"monday\", \"tuesday\", \"wednesday\", \"thursday\", \"friday\", \"saturday\"];\nvar ANIME_CACHE = {};\n\nfunction xorHex(data, key) {\n    var out = \"\";\n    for (var i = 0; i < data.length; i++) {\n        var x = (data.charCodeAt(i) ^ key.charCodeAt(i % key.length)).toString(16);\n        if (x.length < 2) x = \"0\" + x;\n        out += x;\n    }\n    return out;\n}\n\nfunction makeToken() {\n    var dayIdx = new Date(Date.now() + 3 * 3600000).getUTCDay();\n    var key = TOKEN_KEY + \"_\" + DAY_NAMES[dayIdx];\n    var rnd = \"\";\n    for (var i = 0; i < 6; i++) rnd += (Math.random() + 1).toString(36)[2];\n    var payload = {};\n    for (var j = 0; j < rnd.length; j++) payload[String(j)] = rnd.charAt(j);\n    return xorHex(JSON.stringify(payload), key);\n}\n\nfunction apiHeaders() {\n    return {\n        \"Accept\": \"application/json\",\n        \"Cf-Control\": makeToken(),\n        \"User-Agent\": \"Mozilla/5.0\",\n        \"device\": \"browser\",\n        \"language\": \"tr\",\n        \"site\": \"main\"\n    };\n}\n\nfunction apiGet(url) {\n    return Promise.resolve(fetchv2(url, apiHeaders())).then(function(resp) {\n        if (!resp.ok) throw new Error(\"HTTP \" + resp.status);\n        return resp.json();\n    });\n}\n\nfunction parseAnimeId(url) {\n    var m = (url || \"\").match(/\\/(?:anime|watch)\\/(\\d+)/);\n    return m ? m[1] : (url || \"\").replace(/^\\/+|\\/+$/g, \"\");\n}\n\nfunction parseWatchParams(url) {\n    var ms = (url || \"\").match(/[?&]season=(\\d+)/);\n    var me = (url || \"\").match(/[?&]episode=(\\d+)/);\n    return {\n        season: ms ? parseInt(ms[1], 10) : null,\n        episode: me ? parseInt(me[1], 10) : null\n    };\n}\n\nfunction loadAnime(id) {\n    if (ANIME_CACHE[id]) return Promise.resolve(ANIME_CACHE[id]);\n    return apiGet(API_HOST + \"/anime/get?id=\" + encodeURIComponent(id)).then(function(j) {\n        if (!j || !j.success || !j.data) throw new Error(\"anime not found\");\n        ANIME_CACHE[id] = j.data;\n        return j.data;\n    });\n}\n\nfunction buildQueryCandidates(kw) {\n    var list = [];\n    function add(q) {\n        q = (q || \"\").replace(/\\s+/g, \" \").trim();\n        if (q && list.indexOf(q) === -1) list.push(q);\n    }\n    add(kw);\n    if (!kw) return list;\n    var noise = new RegExp(\"\\\\b(season|sezon|b[o\\\\u00f6]l[u\\\\u00fc]m|bolum|episode|izle|watch|t[u\\\\u00fc]rk[c\\\\u00e7]e|dublaj|altyaz|hd|4k|1080p|720p|online|full|anime)\\\\b\", \"gi\");\n    var cleaned = kw.replace(noise, \" \").replace(/\\s+/g, \" \").trim();\n    add(cleaned);\n    var noDigits = cleaned.replace(/\\s+\\d+([._]?\\d+)?\\s*$/, \"\").trim();\n    add(noDigits);\n    var words = cleaned.split(\" \");\n    while (words.length > 2 && list.length < 6) {\n        words.pop();\n        add(words.join(\" \"));\n    }\n    return list;\n}\n\nfunction fetchSearchItems(query) {\n    var urls = [\n        API_HOST + \"/page/search?value=\" + encodeURIComponent(query) + \"&page=1\",\n        API_HOST + \"/page/search?value=\" + encodeURIComponent(query) + \"&page=2\"\n    ];\n    return Promise.all(urls.map(function(u) {\n        return apiGet(u).catch(function() { return null; });\n    })).then(function(results) {\n        var items = [];\n        for (var r = 0; r < results.length; r++) {\n            var j = results[r];\n            if (!j || !j.success || !j.page || !j.page.data) continue;\n            var list = j.page.data;\n            for (var i = 0; i < list.length; i++) {\n                if (list[i]) items.push(list[i]);\n            }\n        }\n        return items;\n    });\n}\n\nfunction searchResults(keyword) {\n    var kw = (keyword || \"\").toString().replace(/\\s+/g, \" \").trim();\n    if (!kw) {\n        var topUrls = [\n            API_HOST + \"/page/top?platform=favorite&page=1\",\n            API_HOST + \"/page/top?platform=favorite&page=2\",\n            API_HOST + \"/page/top?platform=favorite&page=3\"\n        ];\n        return Promise.all(topUrls.map(function(u) {\n            return apiGet(u).catch(function() { return null; });\n        })).then(function(results) {\n            var items = [];\n            var seen = {};\n            for (var r = 0; r < results.length; r++) {\n                var j = results[r];\n                if (!j || !j.success || !j.page || !j.page.data) continue;\n                var list = j.page.data;\n                for (var i = 0; i < list.length; i++) {\n                    var a = list[i];\n                    if (!a || !a.ID || seen[a.ID]) continue;\n                    seen[a.ID] = true;\n                    items.push({\n                        title: a.name || a.ID,\n                        image: a.poster || a.banner || \"\",\n                        href: \"https://anizium.co/anime/\" + a.ID\n                    });\n                }\n            }\n            return JSON.stringify(items);\n        }).catch(function() { return JSON.stringify([]); });\n    }\n    var candidates = buildQueryCandidates(kw);\n    var all = [];\n    var seen = {};\n    function tryNext(i) {\n        if (i >= candidates.length || all.length >= 20) return Promise.resolve(all);\n        return fetchSearchItems(candidates[i]).then(function(items) {\n            for (var k = 0; k < items.length; k++) {\n                var a = items[k];\n                if (!a || !a.ID || seen[a.ID]) continue;\n                seen[a.ID] = true;\n                all.push({\n                    title: a.name || a.ID,\n                    image: a.poster || a.banner || \"\",\n                    href: \"https://anizium.co/anime/\" + a.ID\n                });\n            }\n            return tryNext(i + 1);\n        }).catch(function() {\n            return tryNext(i + 1);\n        });\n    }\n    return tryNext(0).then(function(items) {\n        return JSON.stringify(items);\n    }).catch(function() { return JSON.stringify([]); });\n}\n\nfunction extractDetails(url) {\n    var id = parseAnimeId(url);\n    return loadAnime(id).then(function(a) {\n        var aliases = [];\n        if (a.name_tr && a.name_tr !== a.name) aliases.push(a.name_tr);\n        if (a.name_jp) aliases.push(a.name_jp);\n        return JSON.stringify([{\n            description: a.overview || a.overview_short || \"\",\n            aliases: aliases.join(\", \"),\n            airdate: a.release_year ? String(a.release_year) : \"\"\n        }]);\n    }).catch(function() { return JSON.stringify([{ description: \"\", aliases: \"\", airdate: \"\" }]); });\n}\n\nfunction extractEpisodes(url) {\n    var id = parseAnimeId(url);\n    return loadAnime(id).then(function(a) {\n        var episodes = [];\n        var seasons = a.seasons || [];\n        for (var s = 0; s < seasons.length; s++) {\n            var season = seasons[s];\n            var sn = season.number || (s + 1);\n            var eps = season.episodes || [];\n            for (var e = 0; e < eps.length; e++) {\n                var en = eps[e].number || (e + 1);\n                episodes.push({\n                    href: \"https://anizium.co/watch/\" + id + \"?season=\" + sn + \"&episode=\" + en,\n                    number: sn > 1 ? (sn - 1) * 1000 + en : en\n                });\n            }\n        }\n        if (episodes.length === 0) {\n            episodes.push({ href: \"https://anizium.co/watch/\" + id, number: 1 });\n        }\n        return JSON.stringify(episodes);\n    }).catch(function() { return JSON.stringify([]); });\n}\n\nfunction extractStreamUrl(episodeUrl) {\n    if (!episodeUrl) return Promise.resolve(JSON.stringify({ streams: [], subtitle: \"\" }));\n    var id = parseAnimeId(episodeUrl);\n    var wp = parseWatchParams(episodeUrl);\n    var srcUrl = API_HOST + \"/anime/source?id=\" + encodeURIComponent(id) +\n        \"&site=main&plan=&server=1\";\n    if (wp.season !== null && wp.episode !== null) {\n        srcUrl += \"&season=\" + wp.season + \"&episode=\" + wp.episode;\n    }\n    return apiGet(srcUrl).then(function(j) {\n        if (!j || !j.success) return { streams: [], subtitle: \"\" };\n        var streams = [];\n        var groups = j.groups || [];\n        for (var g = 0; g < groups.length; g++) {\n            var group = groups[g];\n            var items = group.items || [];\n            for (var i = 0; i < items.length; i++) {\n                var item = items[i];\n                if (!item.link) continue;\n                streams.push({\n                    streamUrl: item.link,\n                    title: (group.name ? group.name + \" - \" : \"\") + (item.quality ? item.quality + \"p\" : \"Video\"),\n                    headers: {}\n                });\n            }\n        }\n        var subtitle = \"\";\n        var subs = j.subtitles || [];\n        for (var t = 0; t < subs.length; t++) {\n            if (subs[t].link && subs[t].group === \"tr\") {\n                subtitle = subs[t].link;\n                break;\n            }\n        }\n        if (!subtitle && subs.length > 0 && subs[0].link) subtitle = subs[0].link;\n        if (streams.length === 0) {\n            streams.push({ streamUrl: episodeUrl, title: \"Anizium\", headers: {} });\n        }\n        return { streams: streams, subtitle: subtitle };\n    }).catch(function() {\n        return { streams: [], subtitle: \"\" };\n    }).then(function(result) {\n        return JSON.stringify(result);\n    });\n}\n\n";

    /// The module definition with the embedded script already cached, so nothing ever
    /// fetches `scriptUrl`.
    static func makeDefinition() -> ModuleDefinition? {
        guard let data = manifestJSON.data(using: .utf8),
              var module = try? JSONDecoder().decode(ModuleDefinition.self, from: data) else {
            return nil
        }
        module.scriptContent = script
        return module
    }
}
